// Rebalance: keep the most famous (first-listed) answers in each tier and spill the rest down so the shares land near
// Grey ~27%, Uncommon ~33%, Rare = the remainder (Deep Cut left as authored).
(function () {
  const byId = new Map((window.MOGILLION_PROMPTS || []).map((p) => [p.id, p]));
  for (const r of window.MOGILLION_RETIER) {
    const p = byId.get(r.id);
    if (!p || !/^s[56]-/.test(r.id) || r.__rebalanced) continue;
    r.__rebalanced = true;
    const total = new Set(["t10", "t25", "t50", "t75"].flatMap((t) => (p[t] || []).map((e) => String(e).split("|")[0].toLowerCase()))).size;
    const uniq = (a) => [...new Set(a)];
    const t10 = uniq(r.t10 || []), t25 = uniq(r.t25 || []);
    const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "");
    const listed = new Set([...(r.t10 || []), ...(r.t25 || []), ...(r.t50 || [])].map(norm));
    const stay = (t) => (p[t] || []).filter((e) => !String(e).split("|").some((a) => listed.has(norm(a)))).length;
    const k10 = Math.max(0, Math.round(total * 0.27) - stay("t10")), k25 = Math.max(0, Math.round(total * 0.33) - stay("t25"));
    const spill10 = t10.slice(k10);
    const all25 = uniq(spill10.concat(t25));
    // names already in t10 keep; names spilled from t10 into t25 may also overflow to t50
    r.t10 = t10.slice(0, k10);
    r.t25 = all25.slice(0, Math.max(0, k25 - 0));
    r.t50 = uniq((r.t50 || []).concat(all25.slice(k25)));
  }
})();

// Keep at least ~7 Deep Cuts per prompt: restore a few original Deep Cuts that were only moved down to Rare.
(function () {
  const byId = new Map((window.MOGILLION_PROMPTS || []).map((p) => [p.id, p]));
  const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "");
  for (const r of window.MOGILLION_RETIER) {
    const p = byId.get(r.id);
    if (!p || !/^s[56]-/.test(r.id) || r.__deep) continue;
    r.__deep = true;
    const orig = (p.t75 || []).map((e) => String(e).split("|").map(norm));
    const lists = [r.t10 || [], r.t25 || [], r.t50 || []];
    const listed = new Set(lists.flat().map(norm));
    const remaining = orig.filter((al) => !al.some((a) => listed.has(a))).length;
    let need = 7 - remaining;
    if (need <= 0) continue;
    const t50set = new Set((r.t50 || []).map(norm));
    const t1025 = new Set([...(r.t10 || []), ...(r.t25 || [])].map(norm));
    const cands = orig.filter((al) => al.some((a) => t50set.has(a)) && !al.some((a) => t1025.has(a)));
    const drop = new Set();
    for (const al of cands.slice(-need)) al.forEach((a) => drop.add(a));
    r.t50 = (r.t50 || []).filter((e) => !drop.has(norm(e)));
  }
})();
